# Generated by build.py from recipe.yml for recipe socks5-require-a-socks-login. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://localhost:8080/' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList 'socks5h://127.0.0.1:8082/', '-U', 'app:socks-pw', '--allow-plaintext-auth', '-v', '--log-file', 'open.log' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --max-time 20 -x socks5h://app:socks-pw@127.0.0.1:8082 http://localhost:8080/hello.txt } finally { Stop-Process $server0; Stop-Process $server1 }
